solution:
from collections import deque
def solve(values, k):
    queue = deque()
    result = []
    for i, value in enumerate(values):
        while queue and queue[0] <= i - k:
            queue.popleft()
        while queue and values[queue[-1]] <= value:
            queue.pop()
        queue.append(i)
        if i >= k - 1:
            result.append(values[queue[0]])
    return result

