solution:
def solve(allowed):
    n = len(allowed)
    dp = [0] * (1 << n)
    dp[0] = 1
    for mask in range(1 << n):
        row = mask.bit_count()
        if row == n or dp[mask] == 0:
            continue
        for notebook in range(n):
            bit = 1 << notebook
            if not mask & bit and allowed[row][notebook]:
                dp[mask | bit] += dp[mask]
    return dp[-1]

